package glitch

import data.glitch_lib

weak_tls_names := {"ssl_policy", "tls_policy", "security_policy", "min_tls_version", "minimum_tls_version", "min_protocol_version", "tls_version", "protocol_version"}

weak_key_names := {"key_size", "key_length", "rsa_bits", "bit_length", "key_bits", "modulus_length"}

weak_algo_names := {"algorithm", "encryption_algorithm", "cipher", "cipher_type", "cipher_suite", "cipher_suites", "enabled_ssl_protocols", "allowed_ciphers", "ssl_cipher", "encrypt"}

weak_hash_names := {"signing_algorithm", "certificate_algorithm", "hash_algorithm", "digest_algorithm", "signature_algorithm"}

weak_curve_names := {"curve_name", "elliptic_curve", "curve_type", "named_curve"}

weak_key_spec_names := {"key_spec", "customer_master_key_spec", "kms_key_spec"}

weak_tls_regex := "(?i)(SSLv2|SSLv3|TLSv1\\.0|TLSv1\\.1|TLSv1[^0-9.]|TLS_1_0|TLS_1_1|SSL_3_0)"

weak_algo_regex := "(?i)(\\bDES\\b|3DES|TRIPLE.DES|\\bRC2\\b|\\bRC4\\b|\\bARC4\\b|ARCFOUR|\\bBlowfish\\b|\\bIDEA\\b|EXPORT|\\bNULL\\b|\\banon\\b|_40_|_56_|md5_crypt|MD5WithRSA|\\bmd5\\b|CBC_SHA[^2-9A-Za-z])"

weak_hash_regex := "(?i)(\\bMD4\\b|\\bMD5\\b|\\bSHA1\\b|\\bSHA-1\\b|SHA1WithRSA|MD5WithRSA|ecdsa-with-SHA1)"

weak_curve_regex := "(?i)(secp192r1|prime192v1|secp160r1|sect163k1)"

weak_key_spec_regex := "(?i)(RSA_512|RSA_768|RSA_1024)"

name_in_set(name, names) {
    lower(name) == lower(names[_])
}

name_contains_crypto(name, names) {
    n := names[_]
    contains(lower(name), lower(n))
}

is_weak_for_name(name, value) {
    name_in_set(name, weak_tls_names)
    regex.match(weak_tls_regex, value)
}

is_weak_for_name(name, value) {
    name_in_set(name, weak_algo_names)
    regex.match(weak_algo_regex, value)
}

is_weak_for_name(name, value) {
    name_in_set(name, weak_hash_names)
    regex.match(weak_hash_regex, value)
}

is_weak_for_name(name, value) {
    name_in_set(name, weak_curve_names)
    regex.match(weak_curve_regex, value)
}

is_weak_for_name(name, value) {
    name_in_set(name, weak_key_spec_names)
    regex.match(weak_key_spec_regex, value)
}

is_weak_for_any_crypto(name, value) {
    name_contains_crypto(name, weak_tls_names)
    regex.match(weak_tls_regex, value)
}

is_weak_for_any_crypto(name, value) {
    name_contains_crypto(name, weak_algo_names)
    regex.match(weak_algo_regex, value)
}

is_weak_for_any_crypto(name, value) {
    name_contains_crypto(name, weak_hash_names)
    regex.match(weak_hash_regex, value)
}

is_weak_for_any_crypto(name, value) {
    name_contains_crypto(name, weak_curve_names)
    regex.match(weak_curve_regex, value)
}

is_weak_for_any_crypto(name, value) {
    name_contains_crypto(name, weak_key_spec_names)
    regex.match(weak_key_spec_regex, value)
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    attrs := glitch_lib.all_attributes(parent)
    attr := attrs[_]
    is_weak_for_name(attr.name, attr.value.value)
    attr.value.ir_type == "String"
    result := {
        "type": "sec_weak_crypt",
        "element": attr,
        "path": parent.path,
        "description": "Weak cryptographic algorithm or protocol version configured. (CWE-326)"
    }
}

